&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;Assault in the Fourth Degree (Felony)&lt;/span&gt;&lt;span style="font-family:arial nova light,arial nova light_embeddedfont,arial nova light_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

